
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_hcth_a_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_hcth_a", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-7.062458196935728e-02, -7.090562680845743e-02, -7.131667857081542e-02, -7.191840043968338e-02, -7.279430198822261e-02, -7.404014200684124e-02, -7.569062341550391e-02, -7.741501715010421e-02, -7.741863926809833e-02, -6.957203858062981e-02, -4.916573682109619e-02, -3.864669947650746e-02, -2.846611592904157e-02, -3.536781363084553e-02, -3.269497977486661e-02, -7.449711399310031e-03, 1.278358969854402e-02, 2.867868740947039e-03, -8.692065476182218e-04, -2.243612387187090e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


